import { base, choice, option, t } from "../foundations/courseAuthoring";
import type { CourseQuestion } from "../italian/course/courseTypes";
import type { LocaleText } from "../italian/italianModuleTypes";

/** Authored transfer questions. Checkpoints never require an unavailable recording. */
function pick(id: string, prompt: LocaleText, stimulus: string, answers: [string, string, string], explanation: LocaleText): CourseQuestion {
  const options = answers.map((answer, index) => option(String(index), answer, index === 0 ? explanation : t(
    `Tu as choisi « ${answer} ». La réponse attendue est « ${answers[0]} ». ${explanation.fr}`,
    `You chose “${answer}”. The expected answer is “${answers[0]}”. ${explanation.en}`,
    `Elegiste «${answer}». La respuesta esperada es «${answers[0]}». ${explanation.es}`,
  )));
  const rotation = [...id].reduce((sum, char) => sum + char.charCodeAt(0), 0) % options.length;
  return choice(id, prompt, [...options.slice(rotation), ...options.slice(0, rotation)], "0", explanation, "choice", stimulus);
}
function write(id: string, prompt: LocaleText, model: string, explanation: LocaleText, alternatives: string[] = []): CourseQuestion {
  return { ...base(id, t("Une réponse de mémoire", "A reply from memory", "Una respuesta de memoria"), prompt, explanation), kind: "type", model, accepted: [model, ...alternatives] };
}

